// generatedCustomerBinding is the package-private Runtime execution bridge for customer.
// User Handlers receive it only through an Action-specific capability interface.
type generatedCustomerBinding struct{ execution runtimeext.ActionExecution }

// BindCustomer binds one Runtime Action execution to generated typed operations.
func BindCustomer(execution runtimeext.ActionExecution) generatedCustomerBinding {
	return generatedCustomerBinding{execution: execution}
}

func decodeCustomer(record runtimeext.Record, projection []string) (schema.Customer, error) {
	required := projectedRequiredFields([]string{"company_name", "expected_amount", "lead_id", "source"}, projection)
	result, err := decodeRecord[schema.Customer](record, "customer", required, func(fields map[string]any) error {
		if err := normalizeRecordExactDecimal(fields, "expected_amount", "customer"); err != nil {
			return err
		}
		return nil
	})
	if err != nil {
		return schema.Customer{}, err
	}
	result.UpdatedAt = record.UpdatedAt
	return result, nil
}

func (binding generatedCustomerBinding) NotificationRecipient(ctx context.Context, id schema.CustomerID) (string, error) {
	return runtimeext.ResolveRecordNotificationRecipient(ctx, binding.execution, runtimeext.RecordNotificationRecipientRequest{ObjectKey: "customer", RecordID: string(id)})
}

func (binding generatedCustomerBinding) NotificationRecipientBatch(ctx context.Context, ids []schema.CustomerID) ([]string, error) {
	if err := validateQueryBatchSize(len(ids), "customer"); err != nil {
		return nil, err
	}
	recipients := make([]string, len(ids))
	for index, id := range ids {
		var err error
		recipients[index], err = binding.NotificationRecipient(ctx, id)
		if err != nil {
			return nil, err
		}
	}
	return recipients, nil
}

func (binding generatedCustomerBinding) Get(ctx context.Context, id schema.CustomerID) (schema.Customer, error) {
	result, err := executeRecordQuery(ctx, binding.execution, runtimeext.RecordQuery{Operation: runtimeext.QueryGet, ObjectKey: "customer", RecordID: string(id)})
	if err != nil {
		return schema.Customer{}, err
	}
	if len(result.Records) != 1 {
		return schema.Customer{}, recordDecodeError("customer", fmt.Errorf("get returned %d records", len(result.Records)))
	}
	return decodeCustomer(result.Records[0], nil)
}

func (binding generatedCustomerBinding) GetBatch(ctx context.Context, ids []schema.CustomerID) ([]schema.Customer, error) {
	if err := validateQueryBatchSize(len(ids), "customer"); err != nil {
		return nil, err
	}
	records := make([]schema.Customer, len(ids))
	for index, id := range ids {
		result, err := executeRecordQuery(ctx, binding.execution, runtimeext.RecordQuery{Operation: runtimeext.QueryGet, ObjectKey: "customer", RecordID: string(id)})
		if err != nil {
			return nil, err
		}
		if len(result.Records) != 1 {
			return nil, recordDecodeError("customer", fmt.Errorf("get batch item returned %d records", len(result.Records)))
		}
		records[index], err = decodeCustomer(result.Records[0], nil)
		if err != nil {
			return nil, err
		}
	}
